class QueenScheduler {

    private static final Logger log = Logger.getLogger(QueenScheduler.class.getName());

    private final java.util.Set<Integer> cols = new java.util.HashSet<>();
    private final java.util.Set<Integer> diagDownRight = new java.util.HashSet<>(); // row - col
    private final java.util.Set<Integer> diagDownLeft = new java.util.HashSet<>();  // row + col

    int countPlacements(int n) {
        return backtrack(0, n);
    }

    private int backtrack(int row, int n) {
        if (row == n) {
            return 1;                       // all rows safely filled → one solution
        }
        int count = 0;
        for (int col = 0; col < n; col++) {
            int dr = row - col, dl = row + col;
            if (cols.contains(col) || diagDownRight.contains(dr) || diagDownLeft.contains(dl)) {
                continue;                   // conflict → skip this column
            }
            // place
            cols.add(col); diagDownRight.add(dr); diagDownLeft.add(dl);
            count += backtrack(row + 1, n);
            // undo (backtrack)
            cols.remove(col); diagDownRight.remove(dr); diagDownLeft.remove(dl);
        }
        return count;
    }
}

